{
  "name": "opencode-agentrouter-shim",
  "version": "0.1.0",
  "description": "AgentRouter provider plugin for magpie/OpenCode: Responses reasoning cleanup and optional inline WebP compression, without a local proxy",
  "type": "module",
  "main": "./index.mjs",
  "exports": {
    ".": "./index.mjs",
    "./hooks.mjs": "./hooks.mjs",
    "./sanitize": "./src/sanitize.mjs",
    "./images": "./src/images.mjs"
  },
  "files": [
    "index.mjs",
    "hooks.mjs",
    "src/",
    "README.md",
    "LICENSE"
  ],
  "license": "MIT",
  "engines": {
    "node": ">=22.15.0"
  },
  "scripts": {
    "test": "node --test"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agentrouter",
    "magpie",
    "responses",
    "reasoning"
  ],
  "optionalDependencies": {
    "sharp": "0.35.5"
  },
  "magpie": {
    "name": "AgentRouter Shim",
    "hooks": "./hooks.mjs",
    "icon": "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='8' fill='%23f97316'/%3E%3Ctext x='16' y='22' font-family='system-ui,sans-serif' font-size='13' font-weight='700' text-anchor='middle' fill='white'%3Ear%3C/text%3E%3C/svg%3E",
    "summary": {
      "en": "AgentRouter Responses fix: strips reasoning items and inline image weight for the provider you already configured.",
      "zh": "AgentRouter 的 Responses 修补：清理 reasoning item、压缩内联图片，作用于你已有的供应商，无需另登录。"
    },
    "maxConcurrency": 4,
    "options": {
      "serverUrl": "https://agentrouter.org/v1",
      "apiStyle": "responses",
      "imageMode": "lossy",
      "imageQuality": 90,
      "strict": false,
      "discoverModels": true,
      "hookProviders": [
        "agentrouter"
      ]
    }
  }
}

// magpie / OpenCode provider plugin for AgentRouter.
//
// Two entry points share one core (src/core.mjs):
//   * index.mjs (this file) - declares an AgentRouter provider and rewrites its outgoing
//     Responses bodies inside loader.fetch.
//   * hooks.mjs - a gateway request hook that filters whatever provider is already configured,
//     with no plugin sign-in. Use that one if you already have AgentRouter set up in magpie.
//
// Carried over from agentrouter-responses-shim 2.1.0 (MIT, Copyright (c) 2026 stevenarai):
//   * Responses reasoning-item / redundant-id cleanup (src/sanitize.mjs, verbatim)
//   * optional inline Base64 PNG/JPEG/GIF -> WebP compression (src/images.mjs, lazy sharp)
// Dropped on purpose, because magpie already owns it: listening socket, /healthz, request
// decompression, body-size limits, WebSocket rejection, retries and failover.

import {
  PROVIDER,
  PROVIDER_NAME,
  RESPONSES_PATH,
  DEFAULT_SERVER_URL,
  npmForApi,
  normalizeOptions,
  modelEntry,
  apiStyleFor,
  patternMatches,
  decodeBody,
  apiErrorResponse,
  createCompressor,
  rewriteRequest,
  sanitizeResponsesRequest,
  ShimError,
} from './src/core.mjs';

async function serverPlugin(input, rawOptions) {
  const log = (level, message) => {
    try {
      const result = input?.client?.app?.log?.({ body: { service: PROVIDER, level, message } });
      if (result && typeof result.catch === 'function') result.catch(() => {});
    } catch { /* logging must never break a request */ }
  };
  const options = normalizeOptions(rawOptions, { onWarning: (message) => log('warn', message) });

  // Filter-only mode: the hook in hooks.mjs does the work for the provider you already have.
  // Declaring a provider here would only add a second, unsigned-in card to the provider list.
  if (!options.declareProvider) return {};

  const compressor = createCompressor(options, (error) => log('warn',
    `inline image compression disabled, forwarding images unchanged: ${error?.message ?? error}`));

  const seedModels = () => {
    const models = {};
    for (const [id, patch] of Object.entries(options.models ?? {})) {
      models[id] = modelEntry(id, options, patch && typeof patch === 'object' ? patch : {});
    }
    return models;
  };

  const baseUrlFor = (auth) => {
    const override = auth?.metadata?.serverUrl;
    if (typeof override === 'string' && /^https?:\/\//.test(override)) return override.replace(/\/+$/, '');
    return options.serverUrl;
  };

  return {
    config: async (cfg) => {
      cfg.provider ??= {};
      const entry = cfg.provider[PROVIDER];
      if (entry) {
        // Never fight a config the user wrote; only fill the gaps.
        entry.name ??= PROVIDER_NAME;
        entry.npm ??= npmForApi(options.apiStyle);
        entry.api ??= options.serverUrl;
        entry.models ??= seedModels();
        return;
      }
      cfg.provider[PROVIDER] = {
        name: PROVIDER_NAME,
        npm: npmForApi(options.apiStyle),
        api: options.serverUrl,
        models: seedModels(),
      };
    },

    provider: {
      id: PROVIDER,
      async models(provider, { auth } = {}) {
        const fallback = provider?.models ?? {};
        if (!options.discoverModels || auth?.type !== 'api' || !auth?.key) return fallback;
        const base = baseUrlFor(auth);
        let payload;
        try {
          const response = await globalThis.fetch(`${base}/models`, {
            headers: { authorization: `Bearer ${auth.key}`, accept: 'application/json' },
          });
          if (!response.ok) {
            log('warn', `GET /models answered ${response.status}; keeping the configured model list`);
            return fallback;
          }
          payload = await response.json();
        } catch (error) {
          log('warn', `GET /models failed (${error?.message ?? error}); keeping the configured model list`);
          return fallback;
        }
        const rows = Array.isArray(payload) ? payload : Array.isArray(payload?.data) ? payload.data : [];
        const discovered = {};
        for (const row of rows) {
          const id = typeof row === 'string' ? row : row?.id;
          if (typeof id !== 'string' || id === '') continue;
          if (options.modelAllow?.length && !patternMatches(id, options.modelAllow)) continue;
          if (options.modelDeny?.length && patternMatches(id, options.modelDeny)) continue;
          discovered[id] = modelEntry(id, options, options.models?.[id] ?? fallback[id] ?? {});
        }
        if (!Object.keys(discovered).length) {
          log('warn', 'GET /models returned no usable model ids; keeping the configured model list');
          return fallback;
        }
        // Configured models win over discovery for the same id.
        return { ...discovered, ...fallback };
      },
    },

    auth: {
      provider: PROVIDER,
      methods: [{ type: 'api', label: 'AgentRouter API key', placeholder: 'sk-…' }],
      async loader(getAuth) {
        const auth = await getAuth();
        if (auth?.type !== 'api' || !auth?.key) return {};
        return {
          baseURL: baseUrlFor(auth),
          apiKey: auth.key,
          async fetch(url, init) {
            const target = typeof url === 'string' ? url : url?.url ?? String(url);
            const send = (nextInit) => globalThis.fetch(target, nextInit);
            const bodyText = decodeBody(init?.body);
            if (bodyText == null) return send(init);
            let pathname;
            try {
              pathname = new URL(target).pathname;
            } catch {
              return send(init);
            }
            if (!RESPONSES_PATH.test(pathname)) return send(init);

            let request;
            try {
              request = JSON.parse(bodyText);
            } catch (error) {
              log('warn', `request body is not JSON (${error?.message ?? error}); forwarding unchanged`);
              return send(init);
            }

            let rewrite;
            try {
              rewrite = await rewriteRequest({
                request, bodyText, options, compressor, signal: init?.signal ?? undefined, log,
              });
            } catch (error) {
              if (error instanceof ShimError) {
                log('warn', `refused request: ${error.code} (${error.message})`);
                return apiErrorResponse(error);
              }
              log('warn', `request rewrite failed (${error?.message ?? error}); forwarding unchanged`);
              return send(init);
            }
            if (!rewrite) return send(init);

            const headers = new Headers(init.headers);
            // The body changed: the original length and encoding no longer describe it.
            headers.delete('content-length');
            headers.delete('content-encoding');
            return send({ ...init, headers, body: rewrite.body });
          },
        };
      },
    },
  };
}

// magpie calls every exported function as a plugin and reads `{ id, server }` objects, so only
// these two exports exist: the plugin itself, and a holder the tests reach into.
export const _internal = {
  server: serverPlugin,
  PROVIDER,
  DEFAULT_SERVER_URL,
  modelEntry,
  apiStyleFor,
  normalizeOptions,
  rewriteRequest,
  apiErrorResponse,
  decodeBody,
  patternMatches,
  sanitizeResponsesRequest,
};

export default { id: 'agentrouter-responses-shim', server: serverPlugin };
